1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const BASE_PREMIUM_BY_ITEM_TYPE = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	} as const satisfies Record<string, number>;
53	
54	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
55	
56	const BLOCK_SIZE = 3;
57	const BLOCK_BASE_PREMIUM = 60;
58	const CURSE_SURCHARGE_PERCENT = 50;
59	const HIGH_ENCHANTMENT_THRESHOLD = 5;
60	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
61	const LOYALTY_THRESHOLD_YEARS = 2;
62	const LOYALTY_DISCOUNT_PERCENT = 20;
63	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
64	
65	const basePremiumOf = (item: Item): number =>
66	  BASE_PREMIUM_BY_ITEM_TYPE[item.type as InsurableItemType];
67	
68	interface RiskSurcharge {
69	  appliesTo: (item: Item) => boolean;
70	  percent: number;
71	}
72	
73	const RISK_SURCHARGES: RiskSurcharge[] = [
74	  { appliesTo: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
75	  {
76	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
77	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
78	  },
79	];
80	
81	const itemSurcharge = (item: Item): number =>
82	  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
83	    (sum, surcharge) => sum + percentOf(basePremiumOf(item), surcharge.percent),
84	    0,
85	  );
86	
87	const policySurcharges = (items: Item[]): number =>
88	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
89	
90	const groupByType = (items: Item[]): Item[][] => [
91	  ...items
92	    .reduce(
93	      (groups, item) =>
94	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
95	      new Map<string, Item[]>(),
96	    )
97	    .values(),
98	];
99	
100	const basePremiumOfGroup = (group: Item[]): number =>
101	  group.length === BLOCK_SIZE
102	    ? BLOCK_BASE_PREMIUM
103	    : group.reduce((sum, item) => sum + basePremiumOf(item), 0);
104	
105	const policyBasePremium = (items: Item[]): number =>
106	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
107	
108	interface QuoteContext {
109	  customer: Customer;
110	  previousQuotes: number;
111	}
112	
113	const isLoyal = ({ customer }: QuoteContext): boolean =>
114	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
115	
116	const isFollowUpContract = ({ previousQuotes }: QuoteContext): boolean =>
117	  previousQuotes > 0;
118	
119	interface PolicyAdjustment {
120	  appliesTo: (context: QuoteContext) => boolean;
121	  percent: number;
122	}
123	
124	const POLICY_ADJUSTMENTS: PolicyAdjustment[] = [
125	  { appliesTo: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
126	  { appliesTo: isLoyal, percent: -LOYALTY_DISCOUNT_PERCENT },
127	  { appliesTo: isFollowUpContract, percent: -FOLLOW_UP_DISCOUNT_PERCENT },
128	];
129	
130	const policyAdjustments = (policyBase: number, context: QuoteContext): number =>
131	  POLICY_ADJUSTMENTS.filter((adjustment) => adjustment.appliesTo(context)).reduce(
132	    (sum, adjustment) => sum + percentOf(policyBase, adjustment.percent),
133	    0,
134	  );
135	
136	const quotePremium = (items: Item[], context: QuoteContext): number => {
137	  const policyBase = policyBasePremium(items);
138	  const premiumBeforeFee =
139	    policyBase + policySurcharges(items) + policyAdjustments(policyBase, context);
140	  return Math.ceil(premiumBeforeFee + PROCESSING_FEE);
141	};
142	
143	const INSURANCE_VALUE_BY_ITEM_TYPE = {
144	  sword: 1000,
145	  amulet: 600,
146	  staff: 800,
147	  potion: 400,
148	  rune: 250,
149	  moonstone: 250,
150	} as const satisfies Record<InsurableItemType, number>;
151	
152	const DEDUCTIBLE_PER_DAMAGE = 100;
153	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
154	
155	const insuranceValueOf = (item: Item): number =>
156	  INSURANCE_VALUE_BY_ITEM_TYPE[item.type as InsurableItemType];
157	
158	const capOf = (items: Item[]): number =>
159	  CAP_MULTIPLE_OF_INSURANCE_SUM *
160	  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
161	
162	const payoutFor = (damage: Damage): number =>
163	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
164	
165	const claimResult = (
166	  step: Extract<Step, { op: "claim" }>,
167	  steps: Step[],
168	): StepResult => {
169	  const policy = steps[step.policy];
170	  if (policy?.op !== "quote") throw new Error("claim references no policy");
171	  const payout = step.incident.damages.reduce(
172	    (sum, damage) => sum + payoutFor(damage),
173	    0,
174	  );
175	  return { payout, remainingCap: capOf(policy.items) - payout };
176	};
177	
178	const runStep = (
179	  step: Step,
180	  context: QuoteContext,
181	  steps: Step[],
182	): StepResult =>
183	  step.op === "quote"
184	    ? { premium: quotePremium(step.items, context) }
185	    : claimResult(step, steps);
186	
187	const countQuotesBefore = (steps: Step[], index: number): number =>
188	  steps.slice(0, index).filter((step) => step.op === "quote").length;
189	
190	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
191	  results: steps.map((step, index) =>
192	    runStep(
193	      step,
194	      { customer, previousQuotes: countQuotesBefore(steps, index) },
195	      steps,
196	    ),
197	  ),
198	});
